function App(){const[data,setData]=useState({patients:[],records:{},appointments:[]});const[session,setSession]=useState(null);const[authReady,setAuthReady]=useState(false);const[authMsg,setAuthMsg]=useState('');const[setupKey,setSetupKey]=useState('');const[driveStatus,setDriveStatus]=useState('');const[aiText,setAiText]=useState('');const[aiResult,setAiResult]=useState('');const[aiBusy,setAiBusy]=useState(false);const[showSetupKey,setShowSetupKey]=useState(false);const[paypalSetup,setPaypalSetup]=useState(null);const[login,setLogin]=useState({email:'',password:''});const[view,setView]=useState('dashboard');const[myLibrary,setMyLibrary]=useState(()=>JSON.parse(localStorage.getItem('psicovida_library')||'[]'));const[libDraft,setLibDraft]=useState({title:'',category:'Ansiedad',type:'Ejercicio',content:''});const[selected,setSelected]=useState(null);const[form,setForm]=useState(null);const[q,setQ]=useState('');const[menu,setMenu]=useState(false);const[newPatient,setNewPatient]=useState(false);const[patientFiles,setPatientFiles]=useState([]);const[therapySessions,setTherapySessions]=useState([]);const[isRecording,setIsRecording]=useState(false);const[mediaRecorder,setMediaRecorder]=useState(null);const[audioBlob,setAudioBlob]=useState(null);const[sessionPhoto,setSessionPhoto]=useState(null);const[patientTab,setPatientTab]=useState('resumen');const[libraryFiles,setLibraryFiles]=useState([]);const[sessionDraft,setSessionDraft]=useState({session_date:new Date().toISOString().slice(0,10),note_mode:'free',duration_minutes:60,modality:'Online',participants:'Individual',session_status:'Realizada',emotional_state:'',mood:'',main_topic:'',topics:'',notes:'',objectives:'',interventions:'',patient_response:'',homework:'',clinical_observations:'',next_steps:''});const[draft,setDraft]=useState({name:'',dni:'',phone:'',email:''});
useEffect(()=>{supabase.auth.getSession().then(({data})=>{setSession(data.session);setAuthReady(true)});const{data:sub}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s));return()=>sub.subscription.unsubscribe()},[]);
const loadCloud=async userId=>{const[{data:patients,error:pe},{data:records,error:re},{data:appointments,error:ae}]=await Promise.all([supabase.from('patients').select('*').eq('user_id',userId).order('created_at'),supabase.from('clinical_records').select('*').eq('user_id',userId),supabase.from('appointments').select('*').eq('user_id',userId).order('appointment_date')]);if(pe||re||ae){setAuthMsg((pe||re||ae).message);return}const mappedRecords={};(records||[]).forEach(r=>{mappedRecords[r.patient_id]={...(mappedRecords[r.patient_id]||{}),[r.form_type]:r.content||{}}});setData({patients:patients||[],records:mappedRecords,appointments:(appointments||[]).map(a=>({...a,patientId:a.patient_id,date:a.appointment_date,time:String(a.appointment_time||'').slice(0,5)}))})};
useEffect(()=>{if(session?.user?.id)loadCloud(session.user.id);else setData({patients:[],records:{},appointments:[]})},[session]);
const patient=data.patients.find(p=>p.id===selected);const loadTherapySessions=async()=>{if(!selected||!session)return;const{data,error}=await supabase.from('therapy_sessions').select('*').eq('patient_id',selected).eq('user_id',session.user.id).order('session_date',{ascending:true}).order('created_at',{ascending:true});if(error){setAuthMsg(error.message);return}setTherapySessions(data||[])};useEffect(()=>{if(selected&&session)loadTherapySessions()},[selected,session]);const startAudio=async()=>{try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];const rec=new MediaRecorder(stream);rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=()=>{setAudioBlob(new Blob(chunks,{type:rec.mimeType||'audio/webm'}));stream.getTracks().forEach(t=>t.stop())};rec.start();setMediaRecorder(rec);setIsRecording(true)}catch(e){setAuthMsg('No se pudo acceder al micrófono. Revisa el permiso del navegador.')}};const stopAudio=()=>{if(mediaRecorder&&mediaRecorder.state!=='inactive')mediaRecorder.stop();setIsRecording(false)};const saveTherapySession=async()=>{if(!selected||!session)return;const payload={...sessionDraft,user_id:session.user.id,patient_id:selected,session_number:therapySessions.reduce((m,s)=>Math.max(m,Number(s.session_number)||0),0)+1,duration_minutes:Number(sessionDraft.duration_minutes)||null,mood:sessionDraft.mood?Number(sessionDraft.mood):null};let audio_path=null,photo_path=null;const stamp=Date.now();if(audioBlob){const ext=audioBlob.type.includes('mp4')?'m4a':audioBlob.type.includes('ogg')?'ogg':'webm';audio_path=session.user.id+'/'+selected+'/'+stamp+'-audio.'+ext;const{error}=await supabase.storage.from('session-media').upload(audio_path,audioBlob,{contentType:audioBlob.type||'audio/webm'});if(error){setAuthMsg(error.message);return}}if(sessionPhoto){const ext=(sessionPhoto.name.split('.').pop()||'jpg').toLowerCase();photo_path=session.user.id+'/'+selected+'/'+stamp+'-photo.'+ext;const{error}=await supabase.storage.from('session-media').upload(photo_path,sessionPhoto,{contentType:sessionPhoto.type});if(error){setAuthMsg(error.message);return}}payload.audio_path=audio_path;payload.photo_path=photo_path;const{error}=await supabase.from('therapy_sessions').insert(payload);if(error){setAuthMsg(error.message);return}setSessionDraft({session_date:new Date().toISOString().slice(0,10),note_mode:'free',duration_minutes:60,modality:'Online',participants:'Individual',session_status:'Realizada',emotional_state:'',mood:'',main_topic:'',topics:'',notes:'',objectives:'',interventions:'',patient_response:'',homework:'',clinical_observations:'',next_steps:''});setAudioBlob(null);setSessionPhoto(null);loadTherapySessions()};const fileCats=[['evaluaciones','📋 Evaluaciones e instrumentos','Tests aplicados, escalas, evaluación neuropsicológica.'],['profesionales','👨‍⚕️ Informes de otros profesionales','Neuropediatra, fonoaudióloga, psiquiatra, médico clínico.'],['legal','⚖️ Documentación legal / judicial','Oficios judiciales, pericias y otra documentación legal.'],['otros','📁 Otros documentos','Cualquier archivo que no entre en las categorías anteriores.']];const loadPatientFiles=async()=>{if(!selected||!session)return;const{data,error}=await supabase.storage.from('patient-files').list(session.user.id+'/'+selected,{limit:100,sortBy:{column:'created_at',order:'desc'}});if(error){setPatientFiles([]);return}const all=[];for(const cat of fileCats){const{data:items}=await supabase.storage.from('patient-files').list(session.user.id+'/'+selected+'/'+cat[0],{limit:100,sortBy:{column:'created_at',order:'desc'}});(items||[]).forEach(x=>all.push({...x,category:cat[0]}))}setPatientFiles(all)};useEffect(()=>{if(selected&&session)loadPatientFiles()},[selected,session]);const uploadPatientFile=async(cat,file)=>{if(!file||!selected)return;const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=session.user.id+'/'+selected+'/'+cat+'/'+Date.now()+'-'+safe;const{error}=await supabase.storage.from('patient-files').upload(path,file,{upsert:false});if(error){setAuthMsg(error.message);return}loadPatientFiles()};const openPatientFile=async x=>{const path=session.user.id+'/'+selected+'/'+x.category+'/'+x.name;const{data,error}=await supabase.storage.from('patient-files').createSignedUrl(path,300);if(error){setAuthMsg(error.message);return}window.open(data.signedUrl,'_blank','noopener,noreferrer')};const addPatient=()=>setNewPatient(true);
const createPatient=async e=>{e.preventDefault();if(!draft.name.trim()||!session?.user?.id)return;const{data:p,error}=await supabase.from('patients').insert({user_id:session.user.id,name:draft.name.trim(),dni:draft.dni||null,phone:draft.phone||null,email:draft.email||null,status:'Activo'}).select().single();if(error){setAuthMsg(error.message);return}setData(x=>({...x,patients:[...x.patients,p]}));setDraft({name:'',dni:'',phone:'',email:''});setNewPatient(false);setSelected(p.id);setView('patient')};
const removePatient=async id=>{if(!confirm('¿Eliminar este paciente y sus registros clínicos?'))return;const{error}=await supabase.from('patients').delete().eq('id',id);if(error){setAuthMsg(error.message);return}setData(x=>({...x,patients:x.patients.filter(p=>p.id!==id),records:Object.fromEntries(Object.entries(x.records).filter(([k])=>k!==id)),appointments:x.appointments.filter(a=>a.patientId!==id)}));setView('patients');setSelected(null)};
const updatePatient=async(k,v)=>{setData(x=>({...x,patients:x.patients.map(p=>p.id===selected?{...p,[k]:v}:p)}));const{error}=await supabase.from('patients').update({[k]:v,updated_at:new Date().toISOString()}).eq('id',selected);if(error)setAuthMsg(error.message)};
const record=(data.records[selected]||{})[form]||{};
const saveField=(key,val)=>{const next={...record,[key]:val,_updated:new Date().toISOString()};setData(x=>({...x,records:{...x.records,[selected]:{...(x.records[selected]||{}),[form]:next}}}));clearTimeout(window.__psicovidaSaveTimer);window.__psicovidaSaveTimer=setTimeout(async()=>{const{error}=await supabase.from('clinical_records').upsert({user_id:session.user.id,patient_id:selected,form_type:form,content:next,updated_at:new Date().toISOString()},{onConflict:'patient_id,form_type'});if(error)setAuthMsg(error.message)},450)};
const stats=useMemo(()=>({patients:data.patients.length,records:Object.values(data.records).reduce((n,x)=>n+Object.keys(x).length,0),appointments:data.appointments.length}),[data]);const processSummary=useMemo(()=>{const r=(data.records[selected]||{}).seguimiento||{};const n=Number(r['0-1']||0)||0;const mood=Number(r['0-6']||0);const emotional=String(r['1-4']||r['0-7']||'Sin registrar');const topic=String(r['1-0']||r['0-7']||'Sin registrar');return{sessions:n,duration:n?Math.max(1,Math.ceil(n/4)):'—',mood:mood>=1&&mood<=10?mood:'—',emotional,topic}},[data.records,selected]);
const syncCalendar=async(a,p)=>{try{const r=await fetch('/api/google/calendar/create-event',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({appointmentId:a.id,patientName:p.name,patientEmail:p.email,date:a.appointment_date,time:String(a.appointment_time).slice(0,5),modality:a.modality,duration:60})});const x=await r.json();if(!r.ok)throw new Error(x.error);setAuthMsg('Cita agregada a Google Calendar.')}catch(e){setAuthMsg(e.message)}};const addAppointment=async()=>{if(!data.patients.length){alert('Primero registra un paciente.');return}const patientId=prompt('ID o nombre del paciente',data.patients[0].name);const p=data.patients.find(x=>x.id===patientId||x.name.toLowerCase()===String(patientId||'').toLowerCase());if(!p){alert('Paciente no encontrado.');return}const date=prompt('Fecha (AAAA-MM-DD)',new Date().toISOString().slice(0,10));if(!date)return;const time=prompt('Hora (HH:MM)','19:00');if(!time)return;const{data:a,error}=await supabase.from('appointments').insert({user_id:session.user.id,patient_id:p.id,appointment_date:date,appointment_time:time,status:'Programada',modality:'Online'}).select().single();if(error){setAuthMsg(error.message);return}setData(x=>({...x,appointments:[...x.appointments,{...a,patientId:a.patient_id,date:a.appointment_date,time:String(a.appointment_time).slice(0,5)}]}));if(confirm('¿Agregar esta cita también a tu Google Calendar?'))await syncCalendar(a,p)};
const updateAppointment=async(id,k,v)=>{const dbKey={date:'appointment_date',time:'appointment_time',modality:'modality',status:'status'}[k]||k;setData(x=>({...x,appointments:x.appointments.map(a=>a.id===id?{...a,[k]:v}:a)}));const{error}=await supabase.from('appointments').update({[dbKey]:v,updated_at:new Date().toISOString()}).eq('id',id);if(error)setAuthMsg(error.message)};
const removeAppointment=async id=>{if(!confirm('¿Eliminar esta cita?'))return;const{error}=await supabase.from('appointments').delete().eq('id',id);if(error){setAuthMsg(error.message);return}setData(x=>({...x,appointments:x.appointments.filter(a=>a.id!==id)}))};
const exportBackup=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='psicovida-respaldo-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(url)};
const isAdmin=session?.user?.app_metadata?.role==='admin';const connectDrive=async()=>{setDriveStatus('Preparando conexión…');try{const r=await fetch('/api/google/drive/connect',{headers:{Authorization:'Bearer '+session.access_token}});const x=await r.json();if(!r.ok)throw new Error(x.error||'No se pudo iniciar Google Drive');window.location.href=x.url}catch(e){setDriveStatus(e.message)}};const improveWithAI=async()=>{if(!aiText.trim())return;setAiBusy(true);setAiResult('');try{const r=await fetch('/api/ai/redact',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token},body:JSON.stringify({text:aiText})});const x=await r.json();if(!r.ok)throw new Error(x.error||'No se pudo procesar el texto');setAiResult(x.text||'')}catch(e){setAiResult('Error: '+e.message)}finally{setAiBusy(false)}};const PersonalProfile=()=> <><header><div><p>Cuenta profesional</p><h1>Mi perfil personal</h1></div></header><section className="panel"><span className="adminBadge">{isAdmin?'ADMINISTRADORA':'PROFESIONAL'}</span><h2>Perfil de la cuenta</h2><p className="muted">Este espacio es privado y está asociado a tu sesión de PsicoVida.</p><div className="adminGrid"><article><b>Correo de acceso</b><strong>{session.user.email}</strong><span>Cuenta autenticada</span></article>{isAdmin&&<article><b>Rol</b><strong>Administradora</strong><span>Propietaria de PsicoVida</span></article>}<article><b>Seguridad</b><strong>Sesión activa</strong><span>Acceso privado</span></article></div></section><section className="panel"><span className="eyebrow">ACCESOS PERSONALES</span><h2>Mis herramientas</h2><p className="muted">Accesos directos a servicios externos. PsicoVida no almacena ni sincroniza los archivos de estas cuentas.</p><div className="profileLinks">{isAdmin&&<a className="primary" href="https://www.notion.so/" target="_blank" rel="noopener noreferrer">Abrir mi Notion</a>}<a className="primary" href="https://drive.google.com/drive/my-drive" target="_blank" rel="noopener noreferrer">Abrir mi Google Drive</a></div><p className="muted">{isAdmin?'Notion aparece únicamente en tu perfil de administradora. ':''}Google Drive se abre en la cuenta que tengas iniciada en el navegador.</p></section><section className="panel aiWriter"><span className="eyebrow">AYUDA DE IA</span><h2>Asistente de redacción</h2><p className="muted">Mejora claridad, ortografía y tono profesional con apoyo combinado de IA. Revisa siempre el resultado antes de usarlo en documentación clínica.</p><textarea rows="7" value={aiText} onChange={e=>setAiText(e.target.value)} placeholder="Pega aquí el texto que deseas mejorar…"/><button className="primary" disabled={aiBusy||!aiText.trim()} onClick={improveWithAI}><Sparkles/>{aiBusy?'Redactando…':'Mejorar redacción con IA'}</button>{aiResult&&<div className="aiResult"><b>Versión sugerida</b><textarea rows="9" value={aiResult} onChange={e=>setAiResult(e.target.value)}/><button onClick={()=>navigator.clipboard.writeText(aiResult)}>Copiar texto</button></div>}</section></>;const startSubscription=async()=>{setAuthMsg('Conectando con PayPal…');try{const r=await fetch('/api/paypal/create-subscription',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token}});const x=await r.json();if(!r.ok)throw new Error(x.error||'No se pudo iniciar el pago');if(x.approve)window.location.href=x.approve;else throw new Error('PayPal no devolvió el enlace de aprobación')}catch(e){setAuthMsg(e.message)}};const PlanView=()=> <><header><div><p>Suscripción PsicoVida</p><h1>Plan Profesional</h1></div></header><section className="panel planPanel"><span className="eyebrow">PRECIO FUNDADOR</span><h2>US$ 11.99 <small>/ mes</small></h2><p>Acceso a gestión de pacientes, expedientes, agenda, documentos clínicos y biblioteca profesional.</p><div className="paymentNotice"><b>Pago seguro</b><span>Pago mensual seguro mediante PayPal. Podrás revisar el importe antes de aprobar la suscripción.</span></div><button className="primary" onClick={startSubscription}>Continuar con PayPal</button>{authMsg&&<div className="authMsg">{authMsg}</div>}<small>El cobro se procesa en PayPal. PsicoVida no almacena los datos de tu tarjeta.</small></section></>;
const createPayPalPlan=async()=>{const cleanKey=setupKey.trim();if(!cleanKey){setAuthMsg('Escribe tu clave de configuración de Vercel.');return}setAuthMsg('Creando plan en PayPal Live…');setPaypalSetup(null);try{const r=await fetch('/api/paypal/setup-plan',{method:'POST',headers:{'Content-Type':'application/json','x-setup-key':cleanKey}});const x=await r.json();if(!r.ok)throw new Error(x.error+(x.details?' · '+JSON.stringify(x.details):''));setPaypalSetup(x);setAuthMsg('Plan creado correctamente en PayPal.');setSetupKey('')}catch(e){setAuthMsg(e.message)}};const AdminView=()=> <><header><div><p>PsicoVida</p><h1>Administración</h1></div></header><section className="panel"><span className="adminBadge">ADMINISTRADORA</span><h2>Cuenta propietaria</h2><p><b>{session.user.email}</b></p><p className="muted">Este acceso identifica tu cuenta propietaria de PsicoVida. Las funciones administrativas globales se conectarán mediante backend seguro; no se exponen claves privadas en el navegador.</p><div className="adminGrid"><article><b>Precio fundador</b><strong>US$ 11.99</strong><span>mensual</span></article><article><b>Soporte</b><strong>WhatsApp</strong><span>+51 947 353 536</span></article><article><b>Estado</b><strong>Producción</strong><span>Supabase + Vercel</span></article></div><div className="paymentNotice"><b>Activación PayPal Live</b><span>Escribe aquí la misma clave privada que guardaste como PAYPAL_SETUP_KEY en Vercel. Se envía directamente a tu servidor y no se guarda en PsicoVida.</span><div className="setupKeyRow"><input type={showSetupKey?"text":"password"} autoComplete="off" spellCheck="false" value={setupKey} onChange={e=>setSetupKey(e.target.value)} placeholder="Escribe o pega aquí tu PAYPAL_SETUP_KEY"/><button type="button" className="softAction" onClick={()=>setShowSetupKey(v=>!v)}>{showSetupKey?"Ocultar":"Mostrar"}</button></div><small>{setupKey.length} caracteres ingresados · puedes escribir de corrido o pegar la clave completa</small><button className="primary" onClick={createPayPalPlan}>Crear plan PayPal</button>{authMsg&&<div className="authMsg">{authMsg}</div>}{paypalSetup?.plan_id&&<div className="authMsg"><b>Plan creado:</b> {paypalSetup.plan_id}<br/>Guarda este identificador como PAYPAL_PLAN_ID en Vercel.</div>}</div></section></>;
const go=v=>{setView(v);setMenu(false)};const signIn=async e=>{e.preventDefault();setAuthMsg('');const{error}=await supabase.auth.signInWithPassword({email:login.email,password:login.password});if(error)setAuthMsg(error.message)};const signUp=async()=>{setAuthMsg('');if(!login.email||!login.password){setAuthMsg('Completa correo y contraseña.');return}const{error}=await supabase.auth.signUp({email:login.email,password:login.password});setAuthMsg(error?error.message:'Cuenta creada. Revisa tu correo si Supabase solicita confirmación.')};const signOut=async()=>{await supabase.auth.signOut();setSession(null);setLogin({email:'',password:''})};const Side=()=> <aside className={menu?'open':''}><div className="brand"><div className="logoIdentity" aria-label="PsicoVida"><img src={logoData} alt="PsicoVida Consultorio Psicológico"/></div><button className="closeMenu" onClick={()=>setMenu(false)} aria-label="Cerrar menú"><X/></button></div><nav><button className={view==='dashboard'?'active':''} onClick={()=>go('dashboard')}><LayoutDashboard/>Panel</button><button className={['patients','patient','form'].includes(view)?'active':''} onClick={()=>go('patients')}><Users/>Pacientes</button><button className={view==='agenda'?'active':''} onClick={()=>go('agenda')}><CalendarDays/>Agenda</button><button className={view==='library'?'active':''} onClick={()=>go('library')}><Library/>Mi biblioteca</button><button className={view==='risk'?'active':''} onClick={()=>go('risk')}><ShieldAlert/>Riesgo y seguridad</button><button className={view==='profile'?'active':''} onClick={()=>go('profile')}><User/>Mi perfil</button><button className={view==='plan'?'active':''} onClick={()=>go('plan')}><CreditCard/>Mi plan</button>{isAdmin&&<button className={view==='admin'?'active':''} onClick={()=>go('admin')}><Settings/>Administración</button>}</nav><div className="privacy">🔒 Información clínica · acceso privado</div><div className="supportBox"><b>Soporte PsicoVida</b><a href="mailto:mefersa20@gmail.com">mefersa20@gmail.com</a><a href="https://wa.me/51947353536" target="_blank" rel="noreferrer">WhatsApp: +51 947 353 536</a><small>Atención por WhatsApp</small></div></aside>;
const Dashboard=()=> <><header><div><p>Centro Psicológico PsicoVida</p><h1>Panel clínico</h1></div><button className="primary" onClick={addPatient}><Plus/> Nuevo paciente</button></header><section className="stats"><article><Users/><div><strong>{stats.patients}</strong><span>Pacientes</span></div></article><article><ClipboardList/><div><strong>{stats.records}</strong><span>Registros guardados</span></div></article><article><CalendarDays/><div><strong>{stats.appointments}</strong><span>Citas registradas</span></div></article></section><section className="welcome"><div><span className="eyebrow">GESTIÓN PSICOLÓGICA INTEGRAL</span><h2>Tu espacio clínico, organizado y profesional</h2><p>Centraliza pacientes, sesiones, documentos, agenda y seguimiento en un solo lugar.</p></div><img className="welcomeLogo" src={logoData} alt="" aria-hidden="true"/></section><section className="todayStrip"><div><span className="eyebrow">HOY EN PSICOVIDA</span><h2>Todo lo importante, a primera vista</h2><p>Organiza la práctica clínica sin perder de vista tus pacientes, próximas sesiones y documentación.</p></div><button className="softAction" onClick={()=>go('agenda')}>Ver agenda <ArrowRight/></button></section><section className="panel"><div className="sectionHead"><div><h2>Accesos rápidos</h2><p className="muted">Herramientas principales del consultorio</p></div></div><div className="quick">{docList.slice(0,6).map(([id,n])=><button key={id} onClick={()=>setView('patients')}><FileText/><b>{n}</b><span>Abrir desde expediente</span></button>)}</div></section><section className="featureGrid"><article className="featureCard"><div className="featureIcon"><BookOpen/></div><span className="eyebrow">RECURSOS CLÍNICOS</span><h2>Tu biblioteca profesional</h2><p>Centraliza formularios, entrevistas, objetivos, análisis funcional y planes de tratamiento para trabajar con mayor orden.</p><button onClick={()=>go('documents')}>Explorar documentos <ArrowRight/></button></article><article className="featureCard"><div className="featureIcon"><GraduationCap/></div><span className="eyebrow">DESARROLLO PROFESIONAL</span><h2>Espacio para formación</h2><p>Una sección preparada para incorporar cursos, materiales, guías clínicas y recursos de actualización profesional.</p><button onClick={()=>go('documents')}>Ver recursos <ArrowRight/></button></article><article className="featureCard"><div className="featureIcon"><HeartHandshake/></div><span className="eyebrow">ACOMPAÑAMIENTO</span><h2>Seguimiento centrado en la persona</h2><p>Accede rápidamente al expediente, evolución de sesiones, objetivos terapéuticos y planes de seguridad de cada paciente.</p><button onClick={()=>go('patients')}>Ir a pacientes <ArrowRight/></button></article></section><section className="closingBanner"><Sparkles/><div><span className="eyebrow">PSICOVIDA</span><h2>Menos tiempo administrando. Más tiempo acompañando.</h2><p>Un entorno pensado para mantener tu práctica clínica organizada, clara y profesional.</p></div></section></>;
const Patients=()=> <><header><div><p>Gestión clínica</p><h1>Pacientes</h1></div><button className="primary" onClick={addPatient}><Plus/>Registrar paciente</button></header><section className="panel"><div className="title"><h2>Directorio</h2><div className="search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar paciente"/></div></div>{data.patients.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())).map(p=><div className="patient" key={p.id}><div className="avatar">{p.name[0]}</div><div className="grow"><b>{p.name}</b><small>Admisión: {p.admission}</small></div><button onClick={()=>{setSelected(p.id);setView('patient')}}>Ver expediente</button></div>)}{!data.patients.length&&<div className="empty">Aún no hay pacientes. Registra el primero.</div>}</section></>;
const Patient=()=> patient?<><header><div><button className="back" onClick={()=>setView('patients')}><ChevronLeft/>Pacientes</button><h1>{patient.name}</h1></div><div className="actions"><button onClick={()=>window.print()}><Printer/>Imprimir</button><button className="danger" onClick={()=>removePatient(patient.id)}><Trash2/>Eliminar</button></div></header><section className="panel"><h2>Datos básicos</h2><div className="fields four">{[['DNI','dni'],['Teléfono','phone'],['Email','email'],['Fecha de admisión','admission']].map(([l,k])=><label key={k}>{l}<input type={k==='admission'?'date':'text'} value={patient[k]||''} onChange={e=>updatePatient(k,e.target.value)}/></label>)}</div></section><nav className="patientTabs">{[['resumen','Resumen'],['clinica','Clínica'],['evolucion','Evolución'],['documentos','Documentos']].map(([id,n])=><button key={id} className={patientTab===id?'active':''} onClick={()=>setPatientTab(id)}>{n}</button>)}</nav>{patientTab==='resumen'&&<><section className="patientSummaryGrid"><article className="panel"><span className="eyebrow">SESIONES REALIZADAS</span><strong className="bigMetric">{therapySessions.filter(s=>s.session_status==='Realizada').length}</strong></article><article className="panel"><span className="eyebrow">ÚLTIMA SESIÓN</span><strong>{therapySessions.length?new Date(therapySessions[therapySessions.length-1].session_date+'T00:00:00').toLocaleDateString('es-PE'):'Sin sesiones'}</strong><p>{therapySessions.length?therapySessions[therapySessions.length-1].main_topic||'Sin tema registrado':'Aún no hay notas clínicas.'}</p></article><article className="panel"><span className="eyebrow">CÓMO VIENE EL PROCESO</span><strong>{therapySessions.length?therapySessions[therapySessions.length-1].emotional_state||'Sin registrar':'Sin datos'}</strong><p>{therapySessions.length&&therapySessions[therapySessions.length-1].homework?'Tarea: '+therapySessions[therapySessions.length-1].homework:'Sin tarea pendiente registrada.'}</p></article></section></>}{patientTab==='clinica'&&<><section className="panel therapyHistory"><div className="sectionHead"><div><p className="eyebrow">HISTORIA CLÍNICA</p><h2>📝 Sesiones de terapia</h2><p className="muted">Cada sesión se guarda por separado, con fecha, sin modificar las anteriores.</p></div></div><div className="sessionComposer"><div className="newSessionHead"><h3>Nueva nota de sesión</h3><label>FECHA<input type="date" value={sessionDraft.session_date} onChange={e=>setSessionDraft({...sessionDraft,session_date:e.target.value})}/></label><span>CÓMO QUERÉS ESCRIBIR LA NOTA</span><div className="noteModeTabs">{[['free','Texto libre'],['soap','Formato SOAP'],['structured','Bitácora estructurada']].map(([id,n])=><button type="button" key={id} className={sessionDraft.note_mode===id?'active':''} onClick={()=>setSessionDraft({...sessionDraft,note_mode:id})}>{n}</button>)}</div><small>Cambiar de modo no borra lo que ya escribiste.</small><div className="noteInputModes"><button type="button" className="active">✏️ Escribir</button>{!isRecording?<button type="button" onClick={startAudio}>🎙 Grabar audio</button>:<button type="button" className="recording" onClick={stopAudio}>⏹ Detener</button>}<label className="mediaPick">📷 Subir foto<input type="file" accept="image/jpeg,image/png,image/webp" hidden onChange={e=>setSessionPhoto(e.target.files?.[0]||null)}/></label></div>{audioBlob&&<small>✓ Audio listo para guardar con esta sesión.</small>}{sessionPhoto&&<small>✓ Foto lista: {sessionPhoto.name}</small>}</div><div className="fields two"><label>Duración (min)<input type="number" min="1" value={sessionDraft.duration_minutes} onChange={e=>setSessionDraft({...sessionDraft,duration_minutes:e.target.value})}/></label><label>Modalidad<select value={sessionDraft.modality} onChange={e=>setSessionDraft({...sessionDraft,modality:e.target.value})}><option>Online</option><option>Presencial</option></select></label></div><div className="fields four"><label>Participantes<input value={sessionDraft.participants} onChange={e=>setSessionDraft({...sessionDraft,participants:e.target.value})}/></label><label>Estado emocional<select value={sessionDraft.emotional_state} onChange={e=>setSessionDraft({...sessionDraft,emotional_state:e.target.value})}><option value="">Sin registrar</option><option>Bajo</option><option>Ansioso/a</option><option>Neutro</option><option>Estable</option><option>Bien</option></select></label><label>Ánimo (1–10)<input type="number" min="1" max="10" value={sessionDraft.mood} onChange={e=>setSessionDraft({...sessionDraft,mood:e.target.value})}/></label><label>Estado<select value={sessionDraft.session_status} onChange={e=>setSessionDraft({...sessionDraft,session_status:e.target.value})}><option>Realizada</option><option>Cancelada</option><option>Reprogramada</option></select></label></div>{[['Tema principal','main_topic'],['Temas trabajados','topics'],['Notas de sesión','notes'],['Objetivos trabajados','objectives'],['Intervenciones / técnicas','interventions'],['Respuesta del paciente / evolución','patient_response'],['Tarea para la próxima sesión','homework'],['Notas clínicas / observaciones','clinical_observations'],['Próximos pasos','next_steps']].map(([l,k])=><label key={k}>{l}<textarea rows={k==='notes'?10:3} value={sessionDraft[k]} onChange={e=>setSessionDraft({...sessionDraft,[k]:e.target.value})} placeholder={k==='notes'?(sessionDraft.note_mode==='free'?'Escribe como te salga — sin estructura obligatoria…':sessionDraft.note_mode==='soap'?'S — Subjetivo · O — Objetivo · A — Análisis · P — Plan…':'Registra de forma estructurada lo trabajado en la sesión…'):'Escribe aquí…'}/></label>)}<button className="primary" onClick={saveTherapySession}><Save/>Guardar sesión</button></div><div className="savedSessions"><h3>Sesiones guardadas ({therapySessions.length})</h3>{therapySessions.length?therapySessions.map(s=><article key={s.id}><div><b>Sesión {s.session_number||'—'} — {new Date(s.session_date+'T00:00:00').toLocaleDateString('es-PE')}</b><span>{s.session_status} · {s.modality||'Sin modalidad'}{s.emotional_state?' · '+s.emotional_state:''}</span></div><strong>{s.main_topic||'Sin tema principal'}</strong><p>{s.notes||'Sin notas.'}</p>{s.homework&&<small><b>Tarea:</b> {s.homework}</small>}</article>):<p className="muted">Todavía no hay sesiones guardadas.</p>}</div></section></>}{patientTab==='evolucion'&&<><section className="panel processPanel"><div className="sectionHead"><div><p className="eyebrow">AUTOMÁTICO</p><h2>📊 Resumen del proceso</h2></div></div><div className="adminGrid"><article><b>Sesiones realizadas</b><strong>{processSummary.sessions||'—'}</strong></article><article><b>Duración del proceso</b><strong>{processSummary.duration}{processSummary.duration!=='—'?' m':''}</strong></article><article><b>Estado emocional</b><strong>{processSummary.emotional}</strong></article><article><b>Ánimo promedio (1–10)</b><strong>{processSummary.mood}</strong></article></div><h3>📈 Evolución del estado emocional</h3><p className="muted">Se construye con los estados registrados en las notas de sesión: 5 Bien · 4 Estable · 3 Neutro · 2 Ansioso/a · 1 Bajo.</p><h3>📈 Ánimo del paciente (1–10)</h3><p className="muted">{processSummary.mood==='—'?'Sin ánimo registrado en las sesiones.':'Último ánimo registrado: '+processSummary.mood+'/10'}</p><h3>🏷 Temas más trabajados</h3><div className="topicChip">{processSummary.topic}</div><h3>⏱ Línea de tiempo del proceso</h3><p className="muted">Las notas guardadas en Historia clínica · notas de sesión alimentan automáticamente este seguimiento.</p></section></>}{patientTab==='documentos'&&<><section className="panel"><div className="sectionHead"><div><p className="eyebrow">ACTUALIZADO</p><h2>📎 Archivos externos</h2><p className="muted">PDFs, imágenes o documentos externos del paciente, guardados de forma privada y ordenados por categoría.</p></div></div><div className="externalFiles">{fileCats.map(([id,title,desc])=><article className="fileCategory" key={id}><div><h3>{title}</h3><p className="muted">{desc}</p></div><label className="uploadBtn"><Plus/>Subir<input type="file" accept=".pdf,.jpg,.jpeg,.png,.docx" hidden onChange={e=>{uploadPatientFile(id,e.target.files?.[0]);e.target.value='' }}/></label><div className="fileList">{patientFiles.filter(x=>x.category===id).length?patientFiles.filter(x=>x.category===id).map(x=><button key={x.id||x.name} onClick={()=>openPatientFile(x)}><FileText/>{x.name.replace(/^\d+-/,'')}</button>):<small>Sin archivos.</small>}</div></article>)}</div></section></>}{patientTab==='clinica'&&<><section className="panel"><h2>🏁 Alta / Cierre del proceso</h2><p className="muted">Completa el tipo de cierre cuando corresponda. Al definirlo, el paciente puede pasar a estado de alta según el flujo clínico.</p><div className="fields"><label>Tipo de cierre<select value={(data.records[selected]||{}).cierre?.tipo||''} onChange={async e=>{const tipo=e.target.value;const content={tipo,fecha:new Date().toISOString()};const{error}=await supabase.from('clinical_records').upsert({user_id:session.user.id,patient_id:selected,form_type:'cierre',content,updated_at:new Date().toISOString()},{onConflict:'patient_id,form_type'});if(!error){setData(x=>({...x,records:{...x.records,[selected]:{...(x.records[selected]||{}),cierre:content}}}));if(tipo)updatePatient('status','Alta')}}}><option value="">Sin completar</option><option>Alta terapéutica</option><option>Alta por objetivos alcanzados</option><option>Interrupción / abandono</option><option>Derivación</option><option>Cierre acordado</option></select></label></div></section><section className="panel"><h2>Expediente clínico</h2><div className="docs">{docList.map(([id,n])=><button className="doc" key={id} onClick={()=>{setForm(id);setView('form')}}><FileText/><div><b>{n}</b><small>{(data.records[selected]||{})[id]?<><CheckCircle2/> Guardado</>:'Completar formulario'}</small></div><span>›</span></button>)}</div></section></>}</>:null;
const Form=()=>{const f=forms[form];return <><header><div><button className="back" onClick={()=>setView('patient')}><ChevronLeft/>Expediente</button><p>{patient?.name}</p><h1>{f.title}</h1></div><button onClick={()=>window.print()}><Printer/>Imprimir</button></header><section className="panel form"><div className="notice"><Save/> Los cambios se guardan automáticamente en tu cuenta segura.</div>{f.sections.map(([title,fields],si)=><div className="formsection" key={si}><h2>{title}</h2>{fields.map((label,i)=>{const key=`${si}-${i}`;return <label key={key}>{label}<textarea rows={label.length>45?4:2} value={record[key]||''} onChange={e=>saveField(key,e.target.value)} placeholder="Escribe aquí…"/></label>})}</div>)}<div className="updated">Última actualización: {record._updated?new Date(record._updated).toLocaleString('es-PE'):'Sin guardar'}</div></section></>};
const loadLibraryFiles=async()=>{if(!session)return;const{data,error}=await supabase.storage.from('professional-library').list(session.user.id,{limit:100,sortBy:{column:'created_at',order:'desc'}});if(!error)setLibraryFiles((data||[]).filter(x=>x.name!=='.emptyFolderPlaceholder'))};useEffect(()=>{if(session)loadLibraryFiles()},[session]);const uploadLibraryFile=async file=>{if(!file||!session)return;const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const{error}=await supabase.storage.from('professional-library').upload(session.user.id+'/'+Date.now()+'-'+safe,file);if(error){setAuthMsg(error.message);return}loadLibraryFiles()};const openLibraryFile=async x=>{const{data,error}=await supabase.storage.from('professional-library').createSignedUrl(session.user.id+'/'+x.name,300);if(error){setAuthMsg(error.message);return}window.open(data.signedUrl,'_blank','noopener,noreferrer')};const LibraryView=()=>{const cats=['Ansiedad','Depresión','Estrés','Autoestima','Duelo','Trauma','TOC','Regulación emocional','Dependencia emocional','Límites personales','Relaciones de pareja','Familia','Burnout','Riesgo suicida','Conductas autolesivas','Habilidades sociales','Fobia social','Pánico','Pensamientos intrusivos','TDAH','TEA','Sueño','Violencia psicológica','Culpa y vergüenza'];const addResource=e=>{e.preventDefault();if(!libDraft.title.trim())return;const next=[...myLibrary,{...libDraft,id:Date.now()}];setMyLibrary(next);localStorage.setItem('psicovida_library',JSON.stringify(next));setLibDraft({...libDraft,title:'',content:''})};return <><header><div><p>Recursos profesionales</p><h1>Mi biblioteca clínica</h1><p className="muted">Organiza tus propios ejercicios, materiales y recursos por problemática.</p></div></header><section className="panel"><div className="sectionHead"><div><h2>Mis documentos</h2><p className="muted">Sube documentos propios a tu biblioteca privada. Solo tu cuenta puede acceder a ellos.</p></div><label className="uploadBtn"><Plus/>Subir documento<input type="file" accept=".pdf,.jpg,.jpeg,.png,.docx,.txt" hidden onChange={e=>{uploadLibraryFile(e.target.files?.[0]);e.target.value=''}}/></label></div><div className="fileList">{libraryFiles.length?libraryFiles.map(x=><button key={x.id||x.name} onClick={()=>openLibraryFile(x)}><FileText/>{x.name.replace(/^\d+-/,'')}</button>):<small>Sin documentos en tu biblioteca.</small>}</div></section><section className="panel"><div className="sectionHead"><div><h2>Agregar recurso</h2><p className="muted">Crea tu biblioteca personal dentro de PsicoVida.</p></div><Library/></div><form className="libraryForm" onSubmit={addResource}><label>Título<input value={libDraft.title} onChange={e=>setLibDraft({...libDraft,title:e.target.value})} required/></label><label>Problemática<select value={libDraft.category} onChange={e=>setLibDraft({...libDraft,category:e.target.value})}>{cats.map(x=><option key={x}>{x}</option>)}</select></label><label>Tipo<select value={libDraft.type} onChange={e=>setLibDraft({...libDraft,type:e.target.value})}>{['Ejercicio','Plantilla','Psicoeducación','Metáfora','Tarea terapéutica','Documento'].map(x=><option key={x}>{x}</option>)}</select></label><label className="wide">Contenido / indicaciones<textarea rows="5" value={libDraft.content} onChange={e=>setLibDraft({...libDraft,content:e.target.value})}/></label><button className="primary" type="submit"><Plus/>Agregar a mi biblioteca</button></form></section>{myLibrary.length>0&&<section className="panel"><h2>Mis recursos</h2><div className="myResources">{myLibrary.map(r=><article key={r.id}><span>{r.category} · {r.type}</span><strong>{r.title}</strong><p>{r.content}</p><button className="danger" onClick={()=>{const n=myLibrary.filter(x=>x.id!==r.id);setMyLibrary(n);localStorage.setItem('psicovida_library',JSON.stringify(n))}}>Eliminar</button></article>)}</div></section>}</>};
const Agenda=()=> <><header><div><p>Organización</p><h1>Agenda</h1></div><button className="primary" onClick={addAppointment}><Plus/>Nueva cita</button></header><section className="calendarConnect"><div><span className="eyebrow">GOOGLE CALENDAR</span><h2>Agenda conectada</h2><p>Conecta tu cuenta desde Mi perfil. Al crear una cita podrás agregarla también a tu calendario principal de Google.</p></div><button className="softAction" onClick={()=>go('profile')}>Configurar Google Calendar <ArrowRight/></button></section><section className="panel"><div className="sectionHead"><div><h2>Sesiones programadas</h2><p className="muted">Administra fecha, hora, modalidad y estado de cada atención.</p></div><Clock3/></div><div className="appointments">{(data.appointments||[]).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(a=>{const p=data.patients.find(x=>x.id===a.patientId);return <div className="appointment" key={a.id}><div className="dateBadge"><b>{a.date}</b><span>{a.time}</span></div><div className="grow"><b>{p?.name||'Paciente'}</b><small>{a.modality}</small></div><select value={a.status} onChange={e=>updateAppointment(a.id,'status',e.target.value)}><option>Programada</option><option>Confirmada</option><option>Realizada</option><option>Cancelada</option><option>No asistió</option></select><button className="iconDanger" onClick={()=>removeAppointment(a.id)} title="Eliminar cita"><Trash2/></button></div>})}{!(data.appointments||[]).length&&<div className="empty">No hay citas registradas. Pulsa “Nueva cita” para comenzar.</div>}</div></section></>;const Documents=()=> <><header><div><p>Gestión documental</p><h1>Documentos clínicos</h1></div><button onClick={exportBackup}><Save/>Crear respaldo</button></header><section className="panel"><div className="docs">{docList.map(([id,n])=><div className="doc static" key={id}><FileText/><div><b>{n}</b><small>Disponible dentro del expediente de cada paciente</small></div></div>)}</div></section><section className="panel dataNotice"><ShieldAlert/><div><h2>Protección de datos</h2><p>La información clínica de pacientes, expedientes y agenda se guarda en tu cuenta de Supabase con acceso restringido por profesional. El respaldo JSON permite conservar además una copia personal.</p></div></section></>;const Risk=()=> <><header><div><p>Acceso clínico prioritario</p><h1>Riesgo y seguridad</h1></div></header><section className="panel warning"><ShieldAlert/><div><h2>Evaluación y plan de seguridad</h2><p>Estos módulos se completan dentro del expediente individual. La aplicación no asigna automáticamente un nivel de riesgo ni sustituye el juicio clínico.</p></div></section><section className="panel"><h2>Acceso por paciente</h2>{data.patients.map(p=><div className="patient" key={p.id}><div className="avatar">{p.name[0]}</div><div className="grow"><b>{p.name}</b><small>Evaluación y plan de seguridad</small></div><button onClick={()=>{setSelected(p.id);setView('patient')}}>Abrir expediente</button></div>)}{!data.patients.length&&<div className="empty">No hay pacientes registrados.</div>}</section></>;
if(!authReady)return <div className="loginPage"><section className="loginCard"><h2>PsicoVida</h2><p>Preparando acceso seguro…</p></section></div>;if(!session)return <div className="loginPage"><section className="loginBrand"><img src={logoData} alt="PsicoVida Consultorio Psicológico"/><span className="eyebrow">CONSULTORIO PSICOLÓGICO</span><h1>Tu práctica clínica, en un solo lugar.</h1><p>Organiza pacientes, agenda, seguimiento y documentación con una experiencia profesional y privada.</p><div className="loginBenefits"><span><CheckCircle2/> Expedientes organizados</span><span><CheckCircle2/> Agenda clínica</span><span><CheckCircle2/> Seguimiento terapéutico</span></div></section><section className="loginCard"><div><span className="eyebrow">ACCESO PROFESIONAL</span><h2>Bienvenida a PsicoVida</h2><p>Ingresa a tu espacio de gestión clínica.</p></div><form onSubmit={signIn}><label>Correo electrónico<input type="email" value={login.email} onChange={e=>setLogin({...login,email:e.target.value})} placeholder="tu@correo.com" required/></label><label>Contraseña<input type="password" value={login.password} onChange={e=>setLogin({...login,password:e.target.value})} placeholder="••••••••" required/></label><button className="primary loginButton" type="submit">Ingresar <ArrowRight/></button><button className="softAction signupButton" type="button" onClick={signUp}>Crear cuenta profesional</button>{authMsg&&<div className="authMsg">{authMsg}</div>}</form><small className="loginDisclaimer">Acceso protegido con Supabase Auth. Cada profesional accede únicamente a sus propios datos.</small><small className="ownerHint">Administradora: ingresa o crea tu cuenta con <b>mefersa20@gmail.com</b>.</small></section></div>;return <div className="app"><Side/>{newPatient&&<div className="modalWrap"><div className="modal"><div className="modalHead"><div><p>Nuevo expediente</p><h2>Registrar paciente</h2></div><button onClick={()=>setNewPatient(false)}><X/></button></div><form onSubmit={createPatient}><label>Nombre completo<input autoFocus value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} placeholder="Nombre y apellidos" required/></label><div className="modalGrid"><label>DNI<input value={draft.dni} onChange={e=>setDraft({...draft,dni:e.target.value})}/></label><label>Teléfono<input value={draft.phone} onChange={e=>setDraft({...draft,phone:e.target.value})}/></label></div><label>Correo electrónico<input type="email" value={draft.email} onChange={e=>setDraft({...draft,email:e.target.value})}/></label><div className="modalActions"><button type="button" onClick={()=>setNewPatient(false)}>Cancelar</button><button className="primary" type="submit"><Plus/>Crear expediente</button></div></form></div></div>}<button className="mobileMenu" onClick={()=>setMenu(true)} aria-label="Abrir menú"><Menu/></button>{menu&&<div className="overlay" onClick={()=>setMenu(false)}/>}<main><div className="accountBar"><span><span className="statusDot"/> Sesión segura · {session.user?.email}</span><button onClick={signOut}>Cerrar sesión</button></div>{view==='dashboard'&&<Dashboard/>}{view==='patients'&&<Patients/>}{view==='patient'&&<Patient/>}{view==='form'&&<Form/>}{view==='agenda'&&<Agenda/>}{view==='library'&&<LibraryView/>}{view==='risk'&&<Risk/>}{view==='profile'&&<PersonalProfile/>}{view==='plan'&&<PlanView/>}{view==='admin'&&isAdmin&&AdminView()}</main></div>}
createRoot(document.getElementById('root')).render(<App/>);
